#!/bin/bash
# CIFAR-10 / ResNet50, arm=diag (WCT reference arm). Writes to benchmarks/outputs/lot8_cifar10/resnet50/diag/.
# Generated by benchmarks/slurm/generate_jobs.py — edit that file, not this one.
# See docs/reports/plan_lot8.md §0.11/§1.5 and benchmarks/slurm/README.md.
# Submit from the repository root:  sbatch benchmarks/slurm/train_resnet50_diag.sh

#SBATCH --account=def-msh-ab
#SBATCH --job-name=resnet50_diag
#SBATCH --gpus=h100_1g.10gb:1
#SBATCH --cpus-per-task=8
#SBATCH --mem=16G
#SBATCH --time=04:00:00
#SBATCH --output=benchmarks/slurm/logs/%x-%j.out

# --time: UNMEASURED extrapolation until benchmarks/slurm/calibrate_resnet50.sh has run once.
# Basis: real sacct numbers for the same model, batch size and dataset on this cluster, in
# /Users/baolgr/Documents/AtlasAnalyticsLab/experiments/default/slurm/README.md
# (~85 min for 40 epochs of ResNet50/AdamW -> ~2.1 min/epoch -> ~1h45 at 50 epochs).
# Under the WCT protocol every arm takes ~the reference arm's
# wall-clock time, so all seven arms of one model share one budget. Re-tighten from real
# sacct data after the first submission.

set -euo pipefail
cd "$SLURM_SUBMIT_DIR"

module purge
module load StdEnv/2023 gcc/13.3 cuda/12.6 python/3.11.5

virtualenv --no-download "$SLURM_TMPDIR/env"
source "$SLURM_TMPDIR/env/bin/activate"
pip install --no-index --upgrade pip
pip install --no-index -r requirements-cluster.txt

export PYTHONPATH="$SLURM_SUBMIT_DIR/src"

# Reference arm (plan_lot8.md §0.7): a fixed 50-epoch run whose measured elapsed time is
# every other arm's wall-clock budget. Read it back from the run's manifest.json:
#   python -c "import json;print(json.load(open('benchmarks/outputs/lot8_cifar10/resnet50/diag/manifest.json'))['arms']['diag']['total_s'])"
# and pass it to the other six jobs as --wct-budget (they default to WCT_BUDGET below).
python benchmarks/cifar10_classification.py \
  --model resnet50 \
  --arms diag \
  --epochs 50 \
  --budget-mode epochs \
  --num-workers 8 \
  --no-allow-download \
  --data-root "$SLURM_SUBMIT_DIR/dataset" \
  --output-dir "$SLURM_SUBMIT_DIR/benchmarks/outputs/lot8_cifar10/resnet50/diag"
